module adder_sva (
    input logic       clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic       cin,
    input logic [3:0] sum,
    input logic       cout
);

    // Concatenated carry and sum match 5-bit addition.
    check_total_sum: assert property (
        @(posedge clk)
        {cout, sum} == ({1'b0, a} + {1'b0, b} + {4'b0, cin})
    );

    // Bit 0 sum matches the full-adder XOR equation.
    check_sum0_equation: assert property (
        @(posedge clk)
        sum[0] == (a[0] ^ b[0] ^ cin)
    );

    // Bit 1 sum uses the carry generated by bit 0.
    check_sum1_equation: assert property (
        @(posedge clk)
        sum[1] == (a[1] ^ b[1] ^
                   ((a[0] & b[0]) | (a[0] & cin) | (b[0] & cin)))
    );

    // With b at zero, the adder reduces to a plus carry-in.
    check_b_zero_increment: assert property (
        @(posedge clk)
        (b == 4'h0) |-> ({cout, sum} == ({1'b0, a} + {4'b0, cin}))
    );

    // With a at zero, the adder reduces to b plus carry-in.
    check_a_zero_increment: assert property (
        @(posedge clk)
        (a == 4'h0) |-> ({cout, sum} == ({1'b0, b} + {4'b0, cin}))
    );

    // All-zero inputs produce an all-zero result.
    check_zero_result: assert property (
        @(posedge clk)
        (a == 4'h0 && b == 4'h0 && cin == 1'b0) |-> ({cout, sum} == 5'h00)
    );

    // 0xF plus carry-in overflows to zero with carry out.
    check_boundary_ff_plus_one: assert property (
        @(posedge clk)
        (a == 4'hF && b == 4'h0 && cin == 1'b1) |-> ({cout, sum} == 5'h10)
    );

    // Adding 0x8 and 0x8 generates a carry with zero sum.
    check_msb_carry_case: assert property (
        @(posedge clk)
        (a == 4'h8 && b == 4'h8 && cin == 1'b0) |-> ({cout, sum} == 5'h10)
    );

    // Maximum operands with carry-in produce 0x1F.
    check_max_plus_max_plus_cin: assert property (
        @(posedge clk)
        (a == 4'hF && b == 4'hF && cin == 1'b1) |-> ({cout, sum} == 5'h1F)
    );

endmodule